#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> X(N);
    int H = 0;

    for (int i = 0; i < N; i++) {
        cin >> X[i];
        H = max(H, X[i]);
    }

    for (int h = H; h >= 1; h--) {
        for (int i = 0; i < N; i++) {
            if (i > 0) cout << ' ';
            cout << (X[i] >= h ? 1 : 0);
        }
        cout << '\n';
    }

    return 0;
}
